// Package sqlite implements [store.Store] on SQLite through the pure-Go
// modernc.org/sqlite driver (no CGO). Queries are generated by sqlc from
// queries.sql and the migrations in store/migrations/sqlite.
//
// Concurrency settings, applied to every pooled connection:
//   - at most maxConns (8) open connections, kept idle without expiry: more
//     connections only add writers queueing on SQLite's single write lock,
//     and beyond the busy timeout they fail with SQLITE_BUSY; the pool
//     queues them in Go instead;
//   - journal_mode=WAL: readers do not block the writer;
//   - busy_timeout=5000: a writer waits up to 5 s for the write lock;
//   - _txlock=immediate: transactions take the write lock at BEGIN, so the
//     busy timeout applies and two readers never deadlock upgrading to write;
//   - foreign_keys=ON and synchronous=NORMAL (durable with WAL).
package sqlite

import (
	"bytes"
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/url"
	"time"

	modernc "modernc.org/sqlite"
	sqlite3 "modernc.org/sqlite/lib"

	"github.com/angelia-dev/angelia/internal/store"
)

// maxConns bounds the connection pool; see the package documentation.
const maxConns = 8

// Store is the SQLite engine. It is safe for concurrent use.
type Store struct {
	db *sql.DB
	q  *Queries
}

// Open opens (creating if needed) the database file at path and migrates it
// to the latest schema version. A nil logger means [slog.Default].
func Open(ctx context.Context, path string, logger *slog.Logger) (*Store, error) {
	if logger == nil {
		logger = slog.Default()
	}
	db, err := openDB(path)
	if err != nil {
		return nil, err
	}
	if _, err := migrate(ctx, db, logger, 0); err != nil {
		return nil, errors.Join(err, db.Close())
	}
	return &Store{db: db, q: New(db)}, nil
}

func openDB(path string) (*sql.DB, error) {
	dsn := "file:" + (&url.URL{Path: path}).EscapedPath() + "?_txlock=immediate" +
		"&_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)" +
		"&_pragma=foreign_keys(1)&_pragma=synchronous(NORMAL)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("store: open %s: %w", path, err)
	}
	db.SetMaxOpenConns(maxConns)
	db.SetMaxIdleConns(maxConns)
	db.SetConnMaxIdleTime(0)
	db.SetConnMaxLifetime(0)
	return db, nil
}

// Close closes the database.
func (s *Store) Close() error { return s.db.Close() }

// InTx implements [store.Store].
func (s *Store) InTx(ctx context.Context, fn func(tx store.Tx) error) error {
	return s.withTx(ctx, func(q *Queries) error { return fn(txOps{q: q}) })
}

// withTx runs fn on queries bound to one transaction, committing on nil.
func (s *Store) withTx(ctx context.Context, fn func(q *Queries) error) (err error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("store: begin: %w", err)
	}
	defer func() {
		if rbErr := tx.Rollback(); rbErr != nil && !errors.Is(rbErr, sql.ErrTxDone) {
			err = errors.Join(err, fmt.Errorf("store: rollback: %w", rbErr))
		}
	}()
	if err := fn(s.q.WithTx(tx)); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("store: commit: %w", err)
	}
	return nil
}

// AddVersion implements [store.Tx] in its own statement.
func (s *Store) AddVersion(ctx context.Context, v store.Version) (bool, error) {
	return txOps{q: s.q}.AddVersion(ctx, v)
}

// UpdateVersion implements [store.Tx] in its own statement.
func (s *Store) UpdateVersion(ctx context.Context, v store.Version) error {
	return txOps{q: s.q}.UpdateVersion(ctx, v)
}

// MarkBaselineDone implements [store.Tx] in its own statement.
func (s *Store) MarkBaselineDone(ctx context.Context, watchID string) error {
	return txOps{q: s.q}.MarkBaselineDone(ctx, watchID)
}

// ListVersions implements [store.Tx] outside a transaction.
func (s *Store) ListVersions(ctx context.Context, targetID string) ([]store.Version, error) {
	return txOps{q: s.q}.ListVersions(ctx, targetID)
}

// ListWatches implements [store.Tx] outside a transaction.
func (s *Store) ListWatches(ctx context.Context, targetID string) ([]store.Watch, error) {
	return txOps{q: s.q}.ListWatches(ctx, targetID)
}

// UpdateTarget implements [store.Tx] in its own statement.
func (s *Store) UpdateTarget(ctx context.Context, t store.Target) error {
	return txOps{q: s.q}.UpdateTarget(ctx, t)
}

// AppendEvent implements [store.Tx] in its own transaction.
func (s *Store) AppendEvent(ctx context.Context, e store.Event, ds []store.Delivery) error {
	return s.InTx(ctx, func(tx store.Tx) error { return tx.AppendEvent(ctx, e, ds) })
}

// txOps runs the [store.Tx] writes on q, which may be bound to a transaction.
type txOps struct{ q *Queries }

func (o txOps) AddVersion(ctx context.Context, v store.Version) (bool, error) {
	if v.FirstSeenAt.IsZero() {
		return false, fmt.Errorf("store: version %s@%s: zero first_seen_at: %w", v.TargetID, v.Raw, store.ErrInvalid)
	}
	n, err := o.q.AddVersion(ctx, AddVersionParams{
		TargetID: v.TargetID, Raw: v.Raw, Normalized: v.Normalized, PublishedAt: nullMillis(v.PublishedAt),
		Prerelease: boolInt(v.Prerelease), Yanked: boolInt(v.Yanked), FirstSeenAt: millis(v.FirstSeenAt),
		RemovedAt: nullMillis(v.RemovedAt),
	})
	return n == 1, wrap(err, "add version", v.TargetID+"@"+v.Raw)
}

func (o txOps) UpdateVersion(ctx context.Context, v store.Version) error {
	n, err := o.q.UpdateVersionState(ctx, UpdateVersionStateParams{
		Yanked: boolInt(v.Yanked), RemovedAt: nullMillis(v.RemovedAt), TargetID: v.TargetID, Raw: v.Raw,
	})
	if err == nil && n == 0 {
		err = sql.ErrNoRows
	}
	return wrap(err, "update version", v.TargetID+"@"+v.Raw)
}

func (o txOps) MarkBaselineDone(ctx context.Context, watchID string) error {
	n, err := o.q.MarkBaselineDone(ctx, watchID)
	if err == nil && n == 0 {
		err = sql.ErrNoRows
	}
	return wrap(err, "mark baseline done", watchID)
}

func (o txOps) ListVersions(ctx context.Context, targetID string) ([]store.Version, error) {
	rows, err := o.q.ListVersions(ctx, targetID)
	if err != nil {
		return nil, wrap(err, "list versions", targetID)
	}
	out := make([]store.Version, len(rows))
	for i, r := range rows {
		out[i] = store.Version{
			TargetID: r.TargetID, Raw: r.Raw, Normalized: r.Normalized, PublishedAt: fromNullMillis(r.PublishedAt),
			Prerelease: r.Prerelease != 0, Yanked: r.Yanked != 0, FirstSeenAt: fromMillis(r.FirstSeenAt),
			RemovedAt: fromNullMillis(r.RemovedAt),
		}
	}
	return out, nil
}

func (o txOps) ListWatches(ctx context.Context, targetID string) ([]store.Watch, error) {
	rows, err := o.q.ListWatchesByTarget(ctx, targetID)
	if err != nil {
		return nil, wrap(err, "list watches", targetID)
	}
	out := make([]store.Watch, len(rows))
	for i, r := range rows {
		w, err := watchFromRow(r)
		if err != nil {
			return nil, err
		}
		out[i] = w
	}
	return out, nil
}

func watchFromRow(r Watch) (store.Watch, error) {
	w := store.Watch{ID: r.ID, TargetID: r.TargetID, Policy: json.RawMessage(r.PolicyJson), BaselineDone: r.BaselineDone != 0}
	if err := json.Unmarshal([]byte(r.LabelsJson), &w.Labels); err != nil {
		return store.Watch{}, fmt.Errorf("store: watch %s labels: %w", r.ID, err)
	}
	return w, nil
}

func (o txOps) UpdateTarget(ctx context.Context, t store.Target) error {
	fs, err := rawJSON(t.FetchState, false)
	if err != nil {
		return fmt.Errorf("store: target %s fetch state: %w", t.ID, err)
	}
	if t.NextCheckAt.IsZero() {
		return fmt.Errorf("store: target %s: zero next_check_at: %w", t.ID, store.ErrInvalid)
	}
	n, err := o.q.UpdateTargetState(ctx, UpdateTargetStateParams{
		FetchStateJson: fs, LastCheckedAt: nullMillis(t.LastCheckedAt), NextCheckAt: millis(t.NextCheckAt),
		ErrorCount: t.ErrorCount, ID: t.ID,
	})
	if err == nil && n == 0 {
		err = sql.ErrNoRows
	}
	return wrap(err, "update target", t.ID)
}

func (o txOps) AppendEvent(ctx context.Context, e store.Event, ds []store.Delivery) error {
	payload, err := rawJSON(e.Payload, true)
	if err != nil {
		return fmt.Errorf("store: event %s payload: %w", e.ID, err)
	}
	if e.CreatedAt.IsZero() {
		return fmt.Errorf("store: event %s: zero created_at: %w", e.ID, store.ErrInvalid)
	}
	for _, d := range ds {
		if d.EventID != "" && d.EventID != e.ID {
			return fmt.Errorf("store: delivery %s belongs to event %s, not %s: %w", d.ID, d.EventID, e.ID, store.ErrInvalid)
		}
	}
	if err := o.q.CreateEvent(ctx, CreateEventParams{
		ID: e.ID, WatchID: e.WatchID, Type: e.Type, PayloadJson: payload, CreatedAt: millis(e.CreatedAt),
	}); err != nil {
		return wrap(err, "create event", e.ID)
	}
	for _, d := range ds {
		if err := o.q.CreateDelivery(ctx, CreateDeliveryParams{
			ID: d.ID, EventID: e.ID, SubscriptionID: d.SubscriptionID, Status: d.Status, Attempts: d.Attempts,
			NextAttemptAt: nullMillis(d.NextAttemptAt), LastError: sql.NullString{String: d.LastError, Valid: d.LastError != ""},
		}); err != nil {
			return wrap(err, "create delivery", d.ID)
		}
	}
	return nil
}

// CreateTarget implements [store.Store].
func (s *Store) CreateTarget(ctx context.Context, t store.Target) error {
	coords, err := json.Marshal(nonNil(t.Coordinates)) // sorted keys: canonical
	if err != nil {
		return fmt.Errorf("store: target %s coordinates: %w", t.ID, err)
	}
	fs, err := rawJSON(t.FetchState, false)
	if err != nil {
		return fmt.Errorf("store: target %s fetch state: %w", t.ID, err)
	}
	if t.NextCheckAt.IsZero() {
		return fmt.Errorf("store: target %s: zero next_check_at: %w", t.ID, store.ErrInvalid)
	}
	return wrap(s.q.CreateTarget(ctx, CreateTargetParams{
		ID: t.ID, Kind: t.Kind, CoordinatesJson: string(coords), FetchStateJson: fs,
		LastCheckedAt: nullMillis(t.LastCheckedAt), NextCheckAt: millis(t.NextCheckAt), ErrorCount: t.ErrorCount,
	}), "create target", t.ID)
}

// GetTarget implements [store.Store].
func (s *Store) GetTarget(ctx context.Context, id string) (store.Target, error) {
	r, err := s.q.GetTarget(ctx, id)
	if err != nil {
		return store.Target{}, wrap(err, "get target", id)
	}
	t := store.Target{
		ID: r.ID, Kind: r.Kind, FetchState: json.RawMessage(r.FetchStateJson),
		LastCheckedAt: fromNullMillis(r.LastCheckedAt), NextCheckAt: fromMillis(r.NextCheckAt), ErrorCount: r.ErrorCount,
	}
	if err := json.Unmarshal([]byte(r.CoordinatesJson), &t.Coordinates); err != nil {
		return store.Target{}, fmt.Errorf("store: target %s coordinates: %w", id, err)
	}
	return t, nil
}

// CreateWatch implements [store.Store].
func (s *Store) CreateWatch(ctx context.Context, w store.Watch) error {
	labels, err := json.Marshal(nonNil(w.Labels))
	if err != nil {
		return fmt.Errorf("store: watch %s labels: %w", w.ID, err)
	}
	policy, err := rawJSON(w.Policy, false)
	if err != nil {
		return fmt.Errorf("store: watch %s policy: %w", w.ID, err)
	}
	return wrap(s.q.CreateWatch(ctx, CreateWatchParams{
		ID: w.ID, TargetID: w.TargetID, PolicyJson: policy, LabelsJson: string(labels), BaselineDone: boolInt(w.BaselineDone),
	}), "create watch", w.ID)
}

// GetWatch implements [store.Store].
func (s *Store) GetWatch(ctx context.Context, id string) (store.Watch, error) {
	r, err := s.q.GetWatch(ctx, id)
	if err != nil {
		return store.Watch{}, wrap(err, "get watch", id)
	}
	return watchFromRow(r)
}

// DeleteWatch implements [store.Store].
func (s *Store) DeleteWatch(ctx context.Context, id string) error {
	n, err := s.q.DeleteWatch(ctx, id)
	return deleted(n, err, "delete watch", id)
}

// DeleteSink implements [store.Store].
func (s *Store) DeleteSink(ctx context.Context, id string) error {
	n, err := s.q.DeleteSink(ctx, id)
	return deleted(n, err, "delete sink", id)
}

// DeleteSubscription implements [store.Store].
func (s *Store) DeleteSubscription(ctx context.Context, id string) error {
	n, err := s.q.DeleteSubscription(ctx, id)
	return deleted(n, err, "delete subscription", id)
}

// deleted turns the result of a DELETE by id into an error: ErrNotFound when
// no row matched.
func deleted(n int64, err error, op, id string) error {
	if err == nil && n == 0 {
		err = sql.ErrNoRows
	}
	return wrap(err, op, id)
}

// CreateSink implements [store.Store].
func (s *Store) CreateSink(ctx context.Context, k store.Sink) error {
	cfg := k.ConfigEncrypted
	if cfg == nil {
		cfg = []byte{} // the column is NOT NULL
	}
	return wrap(s.q.CreateSink(ctx, CreateSinkParams{ID: k.ID, Kind: k.Kind, ConfigJsonEncrypted: cfg}), "create sink", k.ID)
}

// CreateSubscription implements [store.Store].
func (s *Store) CreateSubscription(ctx context.Context, sub store.Subscription) error {
	filter, err := rawJSON(sub.Filter, false)
	if err != nil {
		return fmt.Errorf("store: subscription %s filter: %w", sub.ID, err)
	}
	return wrap(s.q.CreateSubscription(ctx, CreateSubscriptionParams{
		ID: sub.ID, FilterJson: filter, SinkID: sub.SinkID, Template: sub.Template,
	}), "create subscription", sub.ID)
}

// ListEventsAfter implements [store.Store].
func (s *Store) ListEventsAfter(ctx context.Context, afterSeq int64, limit int) ([]store.Event, error) {
	if limit <= 0 {
		limit = store.DefaultEventLimit
	}
	rows, err := s.q.ListEventsAfter(ctx, ListEventsAfterParams{Seq: afterSeq, Limit: int64(limit)})
	if err != nil {
		return nil, wrap(err, "list events after", fmt.Sprint(afterSeq))
	}
	out := make([]store.Event, len(rows))
	for i, r := range rows {
		out[i] = store.Event{Seq: r.Seq, ID: r.ID, WatchID: r.WatchID, Type: r.Type, Payload: json.RawMessage(r.PayloadJson), CreatedAt: fromMillis(r.CreatedAt)}
	}
	return out, nil
}

// ListDeliveries implements [store.Store].
func (s *Store) ListDeliveries(ctx context.Context, eventID string) ([]store.Delivery, error) {
	rows, err := s.q.ListDeliveries(ctx, eventID)
	if err != nil {
		return nil, wrap(err, "list deliveries", eventID)
	}
	out := make([]store.Delivery, len(rows))
	for i, r := range rows {
		out[i] = store.Delivery{
			ID: r.ID, EventID: r.EventID, SubscriptionID: r.SubscriptionID, Status: r.Status, Attempts: r.Attempts,
			NextAttemptAt: fromNullMillis(r.NextAttemptAt), LastError: r.LastError.String,
		}
	}
	return out, nil
}

// AcquireLease implements [store.Store].
func (s *Store) AcquireLease(ctx context.Context, name, holder string, now, until time.Time) (bool, error) {
	var ok bool
	err := s.withTx(ctx, func(q *Queries) error {
		if err := q.DeleteExpiredLease(ctx, DeleteExpiredLeaseParams{Name: name, ExpiresAt: millis(now)}); err != nil {
			return wrap(err, "expire lease", name)
		}
		n, err := q.AcquireLease(ctx, AcquireLeaseParams{Name: name, Holder: holder, ExpiresAt: millis(until)})
		ok = n == 1
		return wrap(err, "acquire lease", name)
	})
	return ok, err
}

// ReleaseLease implements [store.Store].
func (s *Store) ReleaseLease(ctx context.Context, name, holder string) error {
	return wrap(s.q.ReleaseLease(ctx, ReleaseLeaseParams{Name: name, Holder: holder}), "release lease", name)
}

// wrap maps driver errors to store sentinels and adds context. nil stays nil.
func wrap(err error, op, id string) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, sql.ErrNoRows) {
		return fmt.Errorf("store: %s %s: %w", op, id, store.ErrNotFound)
	}
	var se *modernc.Error
	if errors.As(err, &se) {
		switch se.Code() {
		case sqlite3.SQLITE_CONSTRAINT_UNIQUE, sqlite3.SQLITE_CONSTRAINT_PRIMARYKEY:
			return fmt.Errorf("store: %s %s: %w: %w", op, id, store.ErrConflict, err)
		case sqlite3.SQLITE_CONSTRAINT_FOREIGNKEY:
			return fmt.Errorf("store: %s %s: %w: %w", op, id, store.ErrInvalidRef, err)
		}
	}
	return fmt.Errorf("store: %s %s: %w", op, id, err)
}

// rawJSON validates m. Empty or null is "{}" when optional, ErrInvalid when
// required.
func rawJSON(m json.RawMessage, required bool) (string, error) {
	if t := bytes.TrimSpace(m); len(t) == 0 || bytes.Equal(t, []byte("null")) {
		if required {
			return "", fmt.Errorf("empty or null JSON: %w", store.ErrInvalid)
		}
		return "{}", nil
	}
	if !json.Valid(m) {
		return "", fmt.Errorf("invalid JSON: %w", store.ErrInvalid)
	}
	return string(m), nil
}

func nonNil(m map[string]string) map[string]string {
	if m == nil {
		return map[string]string{}
	}
	return m
}

func boolInt(b bool) int64 {
	if b {
		return 1
	}
	return 0
}

func millis(t time.Time) int64 { return t.UnixMilli() }

func fromMillis(ms int64) time.Time { return time.UnixMilli(ms).UTC() }

func nullMillis(t time.Time) sql.NullInt64 {
	return sql.NullInt64{Int64: t.UnixMilli(), Valid: !t.IsZero()}
}

func fromNullMillis(n sql.NullInt64) time.Time {
	if !n.Valid {
		return time.Time{}
	}
	return fromMillis(n.Int64)
}
